const incrementArtistCount = `-- name: IncrementArtistCount :exec
;

update artist
set count = count + 1
where id in (/*SLICE:artists*/?)
`

func (q *Queries) IncrementArtistCount(ctx context.Context, artists []int64) error {
	query := incrementArtistCount
	var queryParams []interface{}
	if len(artists) > 0 {
		for _, v := range artists {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:artists*/?", strings.Repeat(",?", len(artists))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:artists*/?", "NULL", 1)
	}
	_, err := q.db.ExecContext(ctx, query, queryParams...)
	return err
}

